-- >>> 002_collection_snapshots.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- Collection Snapshots — "git tags" for content
-- Stores a full snapshot of all entries in a collection at a point in time.
-- Used for one-click rollback after bulk edits, bad imports, etc.

CREATE TABLE IF NOT EXISTS collection_snapshots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    collection_id UUID NOT NULL REFERENCES collections(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    entry_count INTEGER NOT NULL DEFAULT 0,
    entries_data JSONB NOT NULL DEFAULT '[]',  -- full entry objects at snapshot time
    created_by UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL
);

-- Index for fast lookup by collection
CREATE INDEX IF NOT EXISTS idx_snapshots_collection_id ON collection_snapshots(collection_id);
CREATE INDEX IF NOT EXISTS idx_snapshots_created_at ON collection_snapshots(created_at);

-- RLS policies
ALTER TABLE collection_snapshots ENABLE ROW LEVEL SECURITY;

-- DROP first so the file can be re-run safely.
DROP POLICY IF EXISTS snapshots_select ON collection_snapshots;
DROP POLICY IF EXISTS snapshots_insert ON collection_snapshots;
DROP POLICY IF EXISTS snapshots_delete ON collection_snapshots;

-- Snapshots hold full entry dumps (drafts included): admins/editors only.
CREATE POLICY snapshots_select ON collection_snapshots
    FOR SELECT TO authenticated USING (
        EXISTS (
            SELECT 1 FROM profiles
            WHERE id = auth.uid()
            AND role IN ('super_admin', 'admin', 'editor')
        )
    );

CREATE POLICY snapshots_insert ON collection_snapshots
    FOR INSERT WITH CHECK (
        EXISTS (
            SELECT 1 FROM profiles
            WHERE id = auth.uid()
            AND role IN ('super_admin', 'admin')
        )
    );

CREATE POLICY snapshots_delete ON collection_snapshots
    FOR DELETE USING (
        EXISTS (
            SELECT 1 FROM profiles
            WHERE id = auth.uid()
            AND role IN ('super_admin', 'admin')
        )
    );


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- >>> 003_coupon_usage_rpc.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- Atomic coupon usage counter bump
--
-- Used by lib/coupons.ts → confirmRedemption during Stripe webhook processing.
-- The previous pattern (SELECT usage_count, then UPDATE WHERE usage_count = old)
-- did not detect 0-row updates in supabase-js, so concurrent webhooks could
-- both mark redemptions confirmed while the counter only incremented once —
-- silently breaching max_uses_total. This function returns whether the
-- increment actually took effect, via ROW_COUNT after UPDATE.
--
-- jsonb_set preserves sibling keys so concurrent admin edits to other fields
-- of the coupon entry are not lost (previous code spread the whole content blob).

CREATE OR REPLACE FUNCTION bump_coupon_usage(
  entry_id UUID,
  expected_count INTEGER,
  new_count INTEGER
) RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  updated_rows INTEGER;
BEGIN
  UPDATE entries
  SET content = jsonb_set(content, '{usage_count}', to_jsonb(new_count)),
      updated_at = NOW()
  WHERE id = entry_id
    AND COALESCE((content->>'usage_count')::INTEGER, 0) = expected_count;

  GET DIAGNOSTICS updated_rows = ROW_COUNT;
  RETURN updated_rows > 0;
END;
$$;

-- Server-only: the API calls it with the service role. Granting it to
-- anon/authenticated let anyone with the public anon key rewrite usage_count
-- on any entry (e.g. reset a coupon's usage to bypass max_uses_total).
REVOKE ALL ON FUNCTION bump_coupon_usage(UUID, INTEGER, INTEGER) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION bump_coupon_usage(UUID, INTEGER, INTEGER) TO service_role;


